		"feature_antiTranslateTranscript_desc": "Strips translation track parameters from the engagement-panel transcript URL so YouTube serves the original-language captions. Best-effort; works when the original-language track is available.",
		"feature_antiTranslateTranscript_name": "Anti-Translate Transcript",
		"feature_antiTranslate_desc": "Prevent YouTube from auto-translating video titles AND descriptions to your locale. Restores the original-language text on grid thumbnails + watch page.",
		"feature_antiTranslate_name": "Anti-Translate (Original Titles + Descriptions)",
		"feature_astraContextMenu_desc": "Right-click the player or a feed card to get Astra actions: Hide channel, Copy video URL, Copy timestamp link, Open transcript. Default off. On those two surfaces it replaces the native right-click menu; everywhere else on the page the browser menu is untouched.",
		"feature_astraContextMenu_name": "Astra Context Menu",
		"feature_audioAutoGain_desc": "Balance quiet videos toward a comfortable listening level with a bounded, adaptive Web Audio gain stage.",
