		"feature_audioHighPass_desc": "Reduce muddy low-frequency rumble with an 80 Hz high-pass filter in the MAIN-world audio graph.",
		"feature_audioHighPass_name": "Audio High-Pass Filter",
		"feature_audioNormalization_desc": "Compress dynamic range so quiet and loud passages play at similar volume. Uses a DynamicsCompressorNode in the MAIN world audio graph.",
		"feature_audioNormalization_name": "Audio Normalization",
		"feature_audioOnlyPlayback_desc": "Collapse the video and ask the player for the cheapest stream it has, so a watch page costs roughly what a podcast does. YouTube exposes no true audio-only stream to extensions, so the pill reports whether you got one or just the lowest quality. Works on live streams too, where a multi-hour session makes the saving largest.",
		"feature_audioOnlyPlayback_name": "Audio-Only Mode",
		"feature_audioPan_desc": "Shift audio balance left or right via a StereoPannerNode in the MAIN world audio graph. Range -1 (full left) to 1 (full right), 0 = center.",
		"feature_audioPan_name": "Audio Pan",
		"feature_audioParametricEq_desc": "Apply a three-band low, mid, and high EQ in the MAIN-world audio graph. Off by default; each band is bounded to -12 dB to +12 dB.",
		"feature_audioParametricEq_name": "Parametric EQ",
		"feature_audioSyncOffsetMs_desc": "Adjust audio timing relative to video from -500 ms to +500 ms. Positive values add audio delay; negative values use the minimum available Web Audio latency.",
		"feature_audioSyncOffsetMs_name": "Audio Sync Offset",
		"feature_audioTrackLanguage_desc": "Select your preferred audio language through the player bridge without opening or clicking YouTube settings.",
		"feature_audioTrackLanguage_name": "Preferred Audio Track Language",
