		"feature_downloadCobaltFallback_desc": "When Astra Downloader is unreachable, use a self-hosted Cobalt HTTPS instance after setting its origin in the toolbar popup and granting access to that one site. No public Cobalt instance is included.",
		"feature_downloadCobaltFallback_name": "Self-Hosted Cobalt Fallback",
		"feature_downloadHealthPanel_desc": "Show pills for Astra Downloader yt-dlp version, ffmpeg freshness, and PO Token provider state next to the download button. Reads /health every 30 s; no extra storage.",
		"feature_downloadHealthPanel_name": "Downloader Health Pills",
